package com.chubb.apac.claims.modulith.assessment.controller;import com.chubb.apac.claims.modulith.assessment.dto.request.DecisionRequest;import com.chubb.apac.claims.modulith.assessment.dto.response.*;import com.chubb.apac.claims.modulith.assessment.service.AssessmentService;import com.chubb.apac.claims.modulith.common.dto.*;import com.chubb.apac.claims.modulith.common.security.CurrentUser;import com.chubb.apac.claims.modulith.common.util.CorrelationId;import jakarta.validation.Valid;import org.springframework.data.domain.PageRequest;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/staff") @PreAuthorize("hasRole('MANAGER')")
public class ManagerAssessmentController{private final AssessmentService service;public ManagerAssessmentController(AssessmentService s){service=s;}@GetMapping("/assessments/pending")public PageResponse<PendingAssessmentResponse> pending(@AuthenticationPrincipal CurrentUser u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return service.pending(u.markets(),PageRequest.of(page,size));}@PostMapping("/decisions/{claimId}/approve")public ApiResponse<DecisionResponse> approve(@AuthenticationPrincipal CurrentUser u,@PathVariable String claimId,@RequestHeader(value=CorrelationId.HEADER,required=false)String correlation,@Valid @RequestBody DecisionRequest r){return ApiResponse.success(service.approve(claimId,u.userId(),u.markets(),correlation,r));}@PostMapping("/decisions/{claimId}/reject")public ApiResponse<DecisionResponse> reject(@AuthenticationPrincipal CurrentUser u,@PathVariable String claimId,@RequestHeader(value=CorrelationId.HEADER,required=false)String correlation,@Valid @RequestBody DecisionRequest r){return ApiResponse.success(service.reject(claimId,u.userId(),u.markets(),correlation,r));}@GetMapping("/decisions/{claimId}")public ApiResponse<DecisionResponse> decision(@AuthenticationPrincipal CurrentUser u,@PathVariable String claimId){return ApiResponse.success(service.decision(claimId,u.markets()));}}
